@startuml

class Customer {
  + name : string
  + surname : string
  + email : string
  + telephone : string
  + homeAddress : string
}

class Order {
  + totalCost : double
  + estimatedDeliveryTime : time
  + status : string
}

class Dish {
  + name : string
}

class Payment {
  + method : string
  + isSuccessful : boolean
}

Customer "1" -- "*" Order : places
Order "*" -- "1..*" Dish : contains
Order "1" -- "0..1" Payment : paid by

@enduml

